for z in [1.71,3.39]: cube('window horizontal frame',(0,3.51,z),(2.25,.10,.085),frame,.012)
# classroom tables horizontal in rows
for y in [1.92,.27]:
 for x,w in [(-3.7,2.05),(-1.48,2.05),(.74,2.05),(2.96,2.05)]:
  cube('rectangular classroom desktop',(x,y,.78),(w,.75,.055),desk,.015)
